from html.parser import HTMLParser
from pathlib import Path
import hashlib, json, re
base = Path('products/services/sqlite-paid-workshop')
raw = (base / 'raw/manning-write-for-us.html').read_bytes()
class Extract(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.lines = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
        elif tag in ('p', 'li', 'div', 'h1', 'h2', 'h3', 'br', 'section'):
            self.lines.append('\n')
    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.hidden = max(0, self.hidden - 1)
        elif tag in ('p', 'li', 'div', 'h1', 'h2', 'h3', 'section'):
            self.lines.append('\n')
    def handle_data(self, value):
        if not self.hidden:
            self.lines.append(value)
parser = Extract()
parser.feed(raw.decode('utf-8', errors='replace'))
lines = [' '.join(line.split()) for line in ''.join(parser.lines).splitlines() if line.strip()]
pattern = re.compile(r'workshop|curricul|exercise|royalt|payment|compensation|paid|proposal|manuscript|author|course|artificial intelligence', re.I)
indices = sorted({j for i, line in enumerate(lines) if pattern.search(line) for j in range(max(0, i-1), min(len(lines), i+2))})
result = {'url': 'https://www.manning.com/write-for-us', 'sha256': hashlib.sha256(raw).hexdigest(), 'extracted_line_count': len(lines), 'matching_context_lines': len(indices), 'excerpts': [{'line': i+1, 'text': lines[i][:700]} for i in indices[:45]], 'scope': 'Keyword excerpts from the committed HTML. This extraction alone does not establish current compensation, contributor eligibility or any standalone commission. Verify decisive wording directly in the source.'}
out = base / 'manning-scope-readback.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
